using System.Text;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Security;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Exports;
[Authorize(Policy="Permission:"+PermissionCodes.ExportsManage)]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IAuditService audit):PageModel{public async Task<IActionResult> OnPostDownloadAsync(string type,CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();var id=current.AccountId.Value;string csv;int count;if(type=="clients"){var rows=await db.Clients.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted).OrderBy(x=>x.Name).Select(x=>new{x.Name,x.DocumentNumber,x.Email,x.Phone,x.City}).ToListAsync(ct);var b=new StringBuilder("nome,documento,email,telefone,cidade\n");foreach(var x in rows)b.AppendLine(string.Join(',',Q(x.Name),Q(x.DocumentNumber),Q(x.Email),Q(x.Phone),Q(x.City)));csv=b.ToString();count=rows.Count;}else if(type=="services"){var rows=await db.ServiceCatalogItems.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted).OrderBy(x=>x.Name).Select(x=>new{x.Name,x.Description,x.UnitCode,x.StandardPrice,x.IsActive}).ToListAsync(ct);var b=new StringBuilder("nome,descricao,unidade,preco_padrao,ativo\n");foreach(var x in rows)b.AppendLine(string.Join(',',Q(x.Name),Q(x.Description),Q(x.UnitCode),x.StandardPrice.ToString(System.Globalization.CultureInfo.InvariantCulture),x.IsActive));csv=b.ToString();count=rows.Count;}else return BadRequest();var record=new DataExport{AccountId=id,RequestedByUserId=current.UserId,DataType=type,RowCount=count,CompletedAt=DateTime.UtcNow};db.DataExports.Add(record);await db.SaveChangesAsync(ct);await audit.RegisterAsync(current.UserId,"data.exported",nameof(DataExport),record.Id.ToString(),null,new{type,count},null,ct,id);return File(new UTF8Encoding(true).GetBytes(csv),"text/csv; charset=utf-8",$"orcafacil-{type}-{DateTime.UtcNow:yyyyMMdd}.csv");}private static string Q(object? value)=>$"\"{value?.ToString()?.Replace("\"","\"\"")}\"";}
